<?php
require_once __DIR__.'/_common.php';$current_slug='posyandu';require_once ROOT_PATH.'/includes/auth-guard.php';
$stmt=$pdo->query('SELECT w.nama_wilayah,w.kecamatan,w.kabupaten,p.nama_posyandu,p.dusun_rw,p.alamat,pk.nama_puskesmas FROM wilayah w LEFT JOIN posyandu p ON p.id_wilayah=w.id_wilayah LEFT JOIN puskesmas pk ON pk.id_puskesmas=p.id_puskesmas ORDER BY w.nama_wilayah,p.nama_posyandu');$records=$stmt->fetchAll();
$filename='Data_Posyandu_dan_Wilayah_'.date('Ymd_His').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Pragma: no-cache');header('Expires: 0');$out=fopen('php://output','w');fprintf($out,chr(0xEF).chr(0xBB).chr(0xBF));fputcsv($out,array('Nama Wilayah','Kecamatan','Kabupaten/Kota','Nama Posyandu','Dusun / RW','Puskesmas Induk','Alamat Posyandu'));foreach($records as $record){$row=array($record['nama_wilayah'],$record['kecamatan'],$record['kabupaten'],$record['nama_posyandu'],$record['dusun_rw'],$record['nama_puskesmas'],$record['alamat']);foreach($row as &$value){$value=(string)$value;if(preg_match('/^[\s]*[=+\-@]/',$value))$value="'".$value;}unset($value);fputcsv($out,$row);}fclose($out);exit;
